function rules(){const word=$('word-rules');word.replaceChildren();for(const [key,title] of [['singleCharacterColor','单字颜色'],['twoCharacterColorAndEmotion','双字颜色与双字情绪'],['otherwise','其他情况']]){const card=el('div','rule-card');card.append(el('h3',null,title));for(const [value,label] of [['color_first','颜色 → 情绪 → 动物'],['trait_first','情绪 → 颜色 → 动物']]){const lab=el('label'),input=el('input');input.type='checkbox';input.checked=(draft.rules.wordOrderPolicy[key]||[]).includes(value);input.disabled=!writable();input.addEventListener('change',()=>{const values=new Set(draft.rules.wordOrderPolicy[key]);if(input.checked)values.add(value);else values.delete(value);draft.rules.wordOrderPolicy[key]=[...values];changed();});lab.append(input,document.createTextNode(label));card.append(lab);}word.append(card);}
 const pairs=$('pair-rules');pairs.replaceChildren();const options=server.manifest.accessories.map(a=>[a.id,draft.labels[a.id]??a.label]);for(const emotion of server.manifest.emotions){const card=el('div','pair'),name=draft.labels[emotion.id]??emotion.label;card.append(el('h3',null,name),select(`${name}的默认配饰`,options,draft.rules.emotionAccessories[emotion.id],v=>{draft.rules.emotionAccessories[emotion.id]=v;}),el('span','stable-id',emotion.id));pairs.append(card);}}
function render(){if(editing||$('table-dialog').open){viewNeedsRender=true;return;}const summary=$('summary');summary.replaceChildren();for(const [key,title]of groups)summary.append(el('span',null,`${title} ${server.manifest[key]?.length||0}`));rows();rules();}
$('upload-guide').addEventListener('click',()=>{status('请在要替换词条的最后一列点击“上传 PNG”，选择普通非动画 PNG。');$('catalog-tab').click();$('filter').value='animals';$('search').value='';rows();document.querySelector('.upload-button')?.focus();});
$('search').addEventListener('input',()=>{if(server&&commitEdit())rows();});$('filter').addEventListener('change',()=>{if(server&&commitEdit())rows();});$('group-by').addEventListener('change',()=>{if(server&&commitEdit())rows();});
$('reset-view').addEventListener('click',()=>{if(!server||!commitEdit())return;$('search').value='';$('filter').value='all';$('group-by').value='none';columnFilters={};sortKey='type';sortDirection=1;for(const c of columns)widths[c.key]=c.width;persistWidths();rows();});
